#include <Arduino.h>

bool wasExtreme = false;
bool beeping = false;
unsigned long beepStart = 0;

void setup() {
  pinMode(A0, INPUT);
  pinMode(9, OUTPUT);
  pinMode(6, OUTPUT);
  digitalWrite(6, LOW);
}

void loop() {
  const int light = analogRead(A0);
  const int brightness = 255 - (int)((long)light * 255L / 1023L);
  analogWrite(9, brightness);

  const bool extreme = light > 800;
  const unsigned long now = millis();
  if (extreme && !wasExtreme) {
    tone(6, 2000);
    beeping = true;
    beepStart = now;
  }
  if (beeping && (!extreme || now - beepStart >= 120UL)) {
    noTone(6);
    digitalWrite(6, LOW);
    beeping = false;
  }
  wasExtreme = extreme;
  delay(5);
}
